def presentation_for(key):
    """Return fresh presentation data for an explicitly curated catalog key."""
    asset, kind, documentation, download, homepage = _PRESENTATION[key]
    return {
        'icon_url': f'/static/img/service-icons/{asset}',
        'icon_kind': kind,
        'documentation_url': documentation,
        'download_url': download,
        'homepage_url': homepage,
    }
